import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import crypto from 'node:crypto';import * as T from '../static/vendor/three-0.160.1.module.js';
import {build,spec,inspectTopology,segmentHits,containsPoint,inspectCrossings} from '../static/pet-dandelion-pullover-proof-20261027/pullover.mjs';
