const directory=new URL('../static/pet-dandelion-pullover-proof-20261027/',import.meta.url),read=p=>fs.readFileSync(new URL(p,directory)),sha=b=>crypto.createHash('sha256').update(b).digest('hex');const close=(a,b,e=1e-6)=>assert.ok(Math.abs(a-b)<e,String(a)+' != '+b);const withModel=f=>{const m=build(T);try{return f(m);}finally{m.dispose();}};
test('1 preserved original SHA is a garment reference, with explicit unverified anatomy and fit',()=>{assert.equal(sha(read('reference.png')),spec.sourceSHA);assert.equal(spec.sourceSHA,'2bb355ebf7def056df8d43808ab5e32955223a8d29e1cb16261b41dc8ce3faa2');assert.equal(spec.bodyBinding,null);for(const k of['bodyMeasurements','wearingFit','rig','stretchCalibrated','normalGame','unlockSave','newRaw','newDesign','newVillageLibraryCandidate'])assert.equal(spec[k],false);assert.match(spec.backAndInterior,/Authored garment/);});
test('2 actual shell and every closed relief primitive have positive winding and finite normals',()=>withModel(m=>{const x=inspectTopology(T,m.shell.geometry);assert.equal(x.triangles,1960);assert.equal(x.vertices,976);for(const p of m.parts){const t=inspectTopology(T,p.geometry);assert.equal(t.closedEdges,true,p.name);assert.equal(t.badEdges,0);assert.equal(t.degenerateTriangles,0);assert.equal(t.invalidNormals,0);assert.ok(t.signedVolume>0);assert.ok(p.matrixWorld.determinant()>0);}assert.ok(x.signedVolume>.12&&x.signedVolume<.14);}));
test('3 single shared-index material manifold joins both sleeves and has the four expected rim loops',()=>withModel(m=>{const g=m.shell.geometry,idx=g.index,adj=new Map();for(let i=0;i<idx.count;i+=3)for(let k=0;k<3;k++){const a=idx.getX(i+k),b=idx.getX(i+(k+1)%3);if(!adj.has(a))adj.set(a,new Set());adj.get(a).add(b);adj.get(b)?.add(a);}const seen=new Set(),stack=[0];while(stack.length){const a=stack.pop();if(seen.has(a))continue;seen.add(a);stack.push(...adj.get(a));}assert.equal(seen.size,g.attributes.position.count);assert.equal(g.attributes.position.count-idx.count/2+idx.count/3,-4);assert.deepEqual(Object.keys(m.garmentRims).sort(),['hem','left_cuff','neck','right_cuff']);for(const s of m.sleeveRecords){assert.equal(s.attachmentVertices.length,22);for(const v of s.attachmentVertices){assert.ok(adj.get(v).size>=4);assert.ok(idx.array.includes(v));}}assert.equal(m.construction.sleevesShareTorsoBoundaryIndices,true);}));
test('4 twenty actual two-sided finite segments enter the real neck, hem and sleeve interior; solid control is blocked',()=>withModel(m=>{assert.equal(m.passages.length,20);for(const name of Object.keys(m.garmentRims))assert.equal(m.passages.filter(x=>x.opening===name).length,5);for(const p of m.passages)assert.equal(segmentHits(T,m.shell.geometry,p.from,p.to).length,0,p.opening);assert.ok(segmentHits(T,m.shell.geometry,[0,.715,2],[0,.715,0]).length>=2);}));
test('5 garment-only rim frames use exact incident mesh vertices, normals and orthonormal axes',()=>withModel(m=>{for(const[name,r]of Object.entries(m.garmentRims)){assert.equal(m.resolveRim(name),r);const p=new T.Vector3().fromBufferAttribute(m.shell.geometry.attributes.position,r.outerVertex),n=new T.Vector3().fromBufferAttribute(m.shell.geometry.attributes.normal,r.outerVertex).normalize();r.actualSurfacePosition.forEach((x,i)=>close(x,p.toArray()[i]));r.actualSurfaceNormal.forEach((x,i)=>close(x,n.toArray()[i]));const frame=new T.Matrix4().fromArray(r.localFrame),axes=[0,1,2].map(i=>new T.Vector3().setFromMatrixColumn(frame,i));for(const a of axes)close(a.length(),1);close(axes[0].dot(axes[1]),0);close(frame.determinant(),1);assert.equal(r.bodyBinding,null);assert.equal(r.anatomicalSocket,false);for(const i of r.boundaryOuterVertexIndices)assert.ok(i>=0&&i<m.shell.geometry.attributes.position.count/2);}assert.throws(()=>m.resolveRim('body_wrist'),/unknown/);}));
test('6 actual fixed-pose shell has no strict nonadjacent triangle edge/interior crossings',()=>withModel(m=>{const x=inspectCrossings(T,m.shell.geometry);assert.equal(x.triangles,1960);assert.ok(x.candidateNonadjacentAABBPairs>4000);assert.equal(x.strictEdgeInteriorCrossings,0);assert.deepEqual(x.witnesses,[]);}));
test('7 all sixty-five front relief pieces share a strict common-solid witness with the actual shell',()=>withModel(m=>{assert.equal(m.contactWitnesses.length,65);for(const w of m.contactWitnesses){const p=m.parts.find(x=>x.name===w.part);assert.ok(p);assert.equal(containsPoint(T,m.shell,w.point),true,w.part+' shell');assert.equal(containsPoint(T,p,w.point),true,w.part+' relief');}assert.equal(containsPoint(T,m.shell,[0,.715,2]),false);assert.equal(containsPoint(T,m.shell,[0,.715,0]),false);}));
test('8 no original texture, body geometry or animation; bounded resources dispose exactly once',()=>{const m=build(T);assert.deepEqual(m.budget,{meshes:66,geometries:3,materials:5,textures:0,lights:0,triangles:4108});let disposed=0;for(const r of [...m.resources.geometries,...m.resources.materials])r.addEventListener('dispose',()=>disposed++);assert.ok(m.parts.every(p=>(Array.isArray(p.material)?p.material:[p.material]).every(x=>!x.map)));assert.equal(m.inspect().passages.blocked,0);assert.equal(m.dispose(),true);assert.equal(m.dispose(),false);assert.equal(disposed,8);assert.equal(m.group.children.length,0);assert.throws(()=>m.resolveRim('neck'),/disposed/);});
test('9 real geometry remains framed for finite continuous-camera samples at desktop and 390/320 viewport widths',()=>withModel(m=>{for(const [width,height]of[[883,543],[390,350],[320,350]])for(const [yaw,pitch,roll]of[[0,12,0],[90,10,0],[180,12,0],[0,82,0],[0,-80,0],[-135,36,25],[45,-30,-25]]){const v={yaw,pitch,roll,distance:.7},f=fitView(T,m.bounds,v,width/height),cam=new T.PerspectiveCamera(46,width/height,.005,40),a=yaw*Math.PI/180,p=pitch*Math.PI/180,target=new T.Vector3(...f.targetLocal);cam.position.copy(target).addScaledVector(new T.Vector3(Math.sin(a)*Math.cos(p),Math.sin(p),Math.cos(a)*Math.cos(p)),f.actualDistance);cam.lookAt(target);cam.rotateZ(roll*Math.PI/180);cam.updateMatrixWorld(true);for(const mesh of m.parts){const positions=mesh.geometry.attributes.position;for(let i=0;i<positions.count;i++){const q=new T.Vector3().fromBufferAttribute(positions,i).applyMatrix4(mesh.matrixWorld).project(cam);assert.ok(Math.abs(q.x)<.99&&Math.abs(q.y)<.99&&q.z>-1&&q.z<1);}}}assert.throws(()=>fitView(T,m.bounds,{yaw:0,pitch:0,roll:0,distance:1},0),/invalid/);}));
test('10 frozen manifest/certificate pins reproduce; guarded startup reports failures even when cleanup throws',async()=>{const manifest=JSON.parse(read('input-manifest.json'));assert.equal(manifest.source_original.sha256,spec.sourceSHA);for(const p of manifest.files){const d=read(p.path);assert.equal(d.length,p.bytes);assert.equal(sha(d),p.sha256,p.path);}for(const p of manifest.inputs){const d=fs.readFileSync(new URL('../../'+p.path,directory));assert.equal(d.length,p.bytes);assert.equal(sha(d),p.sha256);}withModel(m=>{const c=JSON.parse(read('finite-geometry-certificate.json'));assert.deepEqual(c.geometry,m.inspect());assert.deepEqual(c.staticTriangleCrossings,inspectCrossings(T,m.shell.geometry));});const nodes=Object.fromEntries(['stage','status','report'].map(k=>[k,{dataset:{},textContent:''}])),doc={getElementById:k=>nodes[k]};assert.equal(await startPreview({doc,load:async()=>({start:async()=>{throw new ReferenceError('GarmentMissing is not defined');},cleanup:()=>{throw Error('cleanup');}}),watchMs:1000}),false);const failed=JSON.parse(nodes.report.textContent);assert.equal(failed.startup.cleanupFailed,true);assert.equal(failed.startup.failure.rawMessageStackOrURLSaved,false);assert.equal(nodes.stage.dataset.ready,'false');assert.equal(failureDetails(new Error('https://example.invalid/private?key=secret')).detail,null);});
